function showReservationDetails(){$(".view-reservation").off("click.view").on("click.view",function(){const o=$("#view-reservation"),t=new bootstrap.Modal(o),s=$(this).closest("tr"),e=s.find("th:eq(0)").text();$("#view-reservation .modal-title").html(e+"Details"),t.show()})}function showDashboardToast(){const o=$("#dashboard-toast"),t=new bootstrap.Toast(o,{autohide:!0,delay:2e3});t.show()}$(function(){showReservationDetails(),showDashboardToast()});